import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { type Arm, armHeading, evalArgs, verdict } from "../domain/compare.ts";
import { runProgram, type Spawn, spawnSyncOrNull } from "./run-program.ts";

/**
 * Runs the eval on one plugin folder with `--json FILE`.
 * Returns the exit code (1 when the run cannot start) and the text of the file (`null` when absent).
 */
const evalOf = async (
  plugin: string,
  opts: string[],
  json: string,
  spawn: Spawn,
  log: (line: string) => void,
): Promise<Arm> => {
  let code: number;
  try {
    code =
      runProgram(
        "claude",
        evalArgs(plugin, opts, json),
        { stdio: "inherit" },
        spawn,
      )?.exitCode ?? 1;
  } catch (err) {
    // A word that a Windows shell cannot take safely: say why, and count the run as failed.
    log((err as Error).message);
    code = 1;
  }
  const file = Bun.file(json);
  const result = (await file.exists()) ? await file.text() : null;
  return { code, result };
};

/**
 * Runs the eval on `a`, then on `b`. Returns 0 when both arms exit with 0 and give a valid result, else 1.
 * `spawn` and `log` are the process runner and the output, which a test replaces with fakes.
 */
export const runBoth = async (
  a: string,
  b: string,
  rest: string[],
  spawn: Spawn = spawnSyncOrNull,
  log: (line: string) => void = console.log,
): Promise<number> => {
  const first = path.resolve(a);
  const second = path.resolve(b);
  // The result files go to a new folder, so an old result never counts for this run.
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "claudetto-eval-"));
  try {
    log(armHeading("A", first));
    const x = await evalOf(first, rest, path.join(dir, "a.json"), spawn, log);
    log(armHeading("B", second));
    const y = await evalOf(second, rest, path.join(dir, "b.json"), spawn, log);
    const result = verdict(x, y);
    for (const line of result.lines) log(line);
    return result.code;
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
};
